begin;
insert into auth.users values('00000000-0000-0000-0000-000000000002','{"cafe_sativa_admin":true}');
insert into cs_promo_private.owners(actor) values('00000000-0000-0000-0000-000000000002');
create table public.caller_authority as select public.cs_authorize_character_promo_dispatch('00000000-0000-0000-0000-000000000002') auth;
select public.assert_ok(auth='{"actorId":"00000000-0000-0000-0000-000000000002","actorEpoch":0}'::jsonb,'read-only atomic active owner authority') from caller_authority;
select public.assert_ok((select count(*)=0 from cs_promo_private.attempts),'authorize creates no attempt');
select public.assert_ok(public.cs_authorize_character_promo_dispatch('00000000-0000-0000-0000-000000000099') is null,'unknown actor has no authorization');
select public.assert_ok(not has_function_privilege('service_role','public.cs_claim_character_promo(uuid,text,jsonb)','EXECUTE'),'legacy direct service claim grant removed');
select public.assert_ok(has_function_privilege('service_role','public.cs_claim_character_promo_as_owner(uuid,bigint,uuid,text,jsonb)','EXECUTE'),'service has caller-bound claim only');
select public.assert_ok(not has_function_privilege('authenticated','public.cs_authorize_character_promo_dispatch(uuid)','EXECUTE'),'browser cannot claim caller authority');
select public.assert_ok(public.cs_preflight_character_promo_dispatch('00000000-0000-0000-0000-000000000002',0,'00000000-0000-0000-0000-000000000020',repeat('d',64),public.execution_for('00000000-0000-0000-0000-000000000020'),null),'exact preflight passes read-only');
select public.assert_ok(not public.cs_preflight_character_promo_dispatch('00000000-0000-0000-0000-000000000002',1,'00000000-0000-0000-0000-000000000020',repeat('d',64),public.execution_for('00000000-0000-0000-0000-000000000020'),null),'wrong caller epoch rejected');
select public.assert_ok(not public.cs_preflight_character_promo_dispatch('00000000-0000-0000-0000-000000000002',0,'00000000-0000-0000-0000-000000000020',repeat('a',64),public.execution_for('00000000-0000-0000-0000-000000000020'),null),'conflicting digest rejected');
select public.assert_ok(not public.cs_preflight_character_promo_dispatch('00000000-0000-0000-0000-000000000002',0,'00000000-0000-0000-0000-000000000020',repeat('d',64),jsonb_set(public.execution_for('00000000-0000-0000-0000-000000000020'),'{accountId}','"other"'),null),'wrong exact destination rejected');
select public.assert_ok((select count(*)=0 from cs_promo_private.attempts),'preflight creates no attempt');
savepoint changed_source;
update public.cs_character_promo_drafts set spoken_script='Unreviewed edit';
select public.assert_ok(not public.cs_preflight_character_promo_dispatch('00000000-0000-0000-0000-000000000002',0,'00000000-0000-0000-0000-000000000020',repeat('d',64),public.execution_for('00000000-0000-0000-0000-000000000020'),null),'stale source blocks dispatch');
rollback to changed_source;
release changed_source;
create table public.dispatch_token as select public.cs_claim_character_promo_as_owner('00000000-0000-0000-0000-000000000002',0,'00000000-0000-0000-0000-000000000020',repeat('d',64),public.execution_for('00000000-0000-0000-0000-000000000020')) token;
select public.assert_ok(token is not null,'caller-bound one-time claim') from dispatch_token;
select public.assert_ok((select dispatch_actor='00000000-0000-0000-0000-000000000002' and dispatch_epoch=0 from cs_promo_private.attempts),'caller binding persisted in existing attempt');
select public.assert_ok(public.cs_preflight_character_promo_dispatch('00000000-0000-0000-0000-000000000002',0,'00000000-0000-0000-0000-000000000020',repeat('d',64),public.execution_for('00000000-0000-0000-0000-000000000020'),token),'postclaim exact submitting token allowed') from dispatch_token;
select public.assert_ok(not public.cs_preflight_character_promo_dispatch('00000000-0000-0000-0000-000000000001',0,'00000000-0000-0000-0000-000000000020',repeat('d',64),public.execution_for('00000000-0000-0000-0000-000000000020'),token),'different active owner cannot adopt token') from dispatch_token;
select public.assert_ok(not public.cs_preflight_character_promo_dispatch('00000000-0000-0000-0000-000000000002',0,'00000000-0000-0000-0000-000000000020',repeat('d',64),public.execution_for('00000000-0000-0000-0000-000000000020'),null),'claimed plan cannot preflight as new');
select public.assert_ok(public.cs_claim_character_promo_as_owner('00000000-0000-0000-0000-000000000002',0,'00000000-0000-0000-0000-000000000020',repeat('d',64),public.execution_for('00000000-0000-0000-0000-000000000020')) is null,'duplicate claim denied');
savepoint approval_revoked;
update cs_promo_private.owners set enabled=false where actor='00000000-0000-0000-0000-000000000001';
select public.assert_ok(not public.cs_preflight_character_promo_dispatch('00000000-0000-0000-0000-000000000002',0,'00000000-0000-0000-0000-000000000020',repeat('d',64),public.execution_for('00000000-0000-0000-0000-000000000020'),token),'original approver authority remains required separately from caller') from dispatch_token;
rollback to approval_revoked;
release approval_revoked;
savepoint scheduled_terminal;
select public.assert_ok(public.cs_finish_character_promo('00000000-0000-0000-0000-000000000020',token,'scheduled',jsonb_build_object('state','scheduled','providerId','fixture','providerUuid','fixture-uuid','snapshotDigest',repeat('d',64),'videoSha256',s->>'videoSha256','network',s->>'network','accountId',s->>'accountId','brandId',s->>'brandId','userId',s->>'userId','caption',s->>'caption','scheduledAt',s->>'scheduledAt','timezone',s->>'timezone')),'fixture exact scheduling receipt') from dispatch_token cross join (select public.execution_for('00000000-0000-0000-0000-000000000020') s) x;
select public.assert_ok(not public.cs_preflight_character_promo_dispatch('00000000-0000-0000-0000-000000000002',0,'00000000-0000-0000-0000-000000000020',repeat('d',64),public.execution_for('00000000-0000-0000-0000-000000000020'),token),'scheduled token cannot authorize new provider call') from dispatch_token;
rollback to scheduled_terminal;
release scheduled_terminal;
update cs_promo_private.owners set enabled=false where actor='00000000-0000-0000-0000-000000000002';
update cs_promo_private.owners set enabled=true where actor='00000000-0000-0000-0000-000000000002';
select public.assert_ok(not public.cs_preflight_character_promo_dispatch('00000000-0000-0000-0000-000000000002',0,'00000000-0000-0000-0000-000000000020',repeat('d',64),public.execution_for('00000000-0000-0000-0000-000000000020'),token),'revoke restore cannot revive old dispatch epoch') from dispatch_token;
select public.assert_ok(not public.cs_preflight_character_promo_dispatch('00000000-0000-0000-0000-000000000002',1,'00000000-0000-0000-0000-000000000020',repeat('d',64),public.execution_for('00000000-0000-0000-0000-000000000020'),token),'fresh epoch cannot adopt old attempt') from dispatch_token;
select public.assert_ok(public.cs_finish_character_promo('00000000-0000-0000-0000-000000000020',token,'submission_unknown',null),'revoked request may persist unknown outcome') from dispatch_token;
select public.assert_ok((select count(*)=1 and min(state)='submission_unknown' from cs_promo_private.attempts),'unknown outcome remains permanent');
select public.assert_ok(public.cs_claim_character_promo_as_owner('00000000-0000-0000-0000-000000000002',1,'00000000-0000-0000-0000-000000000020',repeat('d',64),public.execution_for('00000000-0000-0000-0000-000000000020')) is null,'unknown request cannot retry at new epoch');
create table public.legacy_token as select public.cs_claim_character_promo('00000000-0000-0000-0000-000000000021',repeat('d',64),public.execution_for('00000000-0000-0000-0000-000000000021')) token;
select public.assert_ok(token is not null,'fixture legacy unbound attempt exists') from legacy_token;
select public.assert_ok(not public.cs_preflight_character_promo_dispatch('00000000-0000-0000-0000-000000000002',1,'00000000-0000-0000-0000-000000000021',repeat('d',64),public.execution_for('00000000-0000-0000-0000-000000000021'),token),'legacy unbound token stays manual hold') from legacy_token;
select public.assert_ok(public.cs_claim_character_promo_as_owner('00000000-0000-0000-0000-000000000002',1,'00000000-0000-0000-0000-000000000021',repeat('d',64),public.execution_for('00000000-0000-0000-0000-000000000021')) is null,'wrapper cannot adopt legacy attempt');
commit;
